struct AuthGuard {
    struct context {};
    void before_handle(crow::request& req, crow::response& res, context&) {
        if (!authorized(req)) { res.code = 401; res.end(); }   // short-circuit
    }
    void after_handle(crow::request&, crow::response&, context&) {}
};

crow::App<AuthGuard> app;
CROW_ROUTE(app, "/orders/<int>").CROW_MIDDLEWARES(app, AuthGuard)(
    [](int id) { return crow::response(render_order(id)); });
app.port(8080).multithreaded().run();
